import re

def is_samepatterns(words, patterns):
    pattern_map = {}
    word_map = {}
    for word, pattern in zip(words, patterns):
        if pattern not in pattern_map:
            pattern_map[pattern] = word
        if word not in word_map:
            word_map[word] = pattern
        if pattern_map.get(pattern)!= word or word_map.get(word)!= pattern:
            return False
    return True
```

